import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { asString, useSearchParam } from '../../url/useSearchParam';
import { useSubmitOnce } from '../../query/useSubmitOnce';
import { templatesKey, useTemplates, type Template } from './useTemplates';

// The sheet's claim templates and the form that saves one: a blank name, or an amount the claim form
// would refuse, is refused; saving a name again replaces that template. Claims already made from a
// template keep the amount and note they were made with.
export function TemplatePanel() {
  const [sheet] = useSearchParam('sheet', asString);
  const [user] = useSearchParam('user', asString);
  const templates = useTemplates(sheet);
  const [name, setName] = useState('');
  const [amount, setAmount] = useState('');
  const [note, setNote] = useState('');
  const queryClient = useQueryClient();
  const submitOnce = useSubmitOnce();
  const save = useMutation({
    mutationFn: (body: { name: string; amount: string; note: string }) =>
      postJson<Template[]>(`/api/sheets/${encodeURIComponent(sheet)}/templates`, { ...body, user }),
    onSuccess: (saved) => {
      setName('');
      setAmount('');
      setNote('');
      queryClient.setQueryData(templatesKey(sheet), saved);
    },
  });
  const changed = (set: (v: string) => void) => (v: string) => {
    set(v);
    save.reset();
  };
  return (
    <>
      <ul data-testid="template-list">
        {templates.map((t) => (
          <li key={t.name} data-testid={`template-row-${t.name}`}>
            <span data-testid="template-name">{t.name}</span>{' '}
            <span data-testid="template-amount">{t.amount}</span>{' '}
            <span data-testid="template-note">{t.note}</span>
          </li>
        ))}
      </ul>
      <form
        data-testid="template-form"
        onSubmit={(e) => {
          e.preventDefault();
          submitOnce(() => {
            save.reset();
            return save.mutateAsync({ name: name.trim(), amount: amount.trim(), note });
          });
        }}
      >
        <input data-testid="template-form-name" value={name} placeholder="Template name" onChange={(e) => changed(setName)(e.target.value)} />{' '}
        <input
          data-testid="template-form-amount"
          value={amount}
          placeholder="Amount"
          inputMode="decimal"
          onChange={(e) => changed(setAmount)(e.target.value)}
        />{' '}
        <input data-testid="template-form-note" value={note} placeholder="Note" onChange={(e) => changed(setNote)(e.target.value)} />{' '}
        <button type="submit" data-testid="template-form-submit">Save template</button>
        {save.isError && (
          <span data-testid="template-form-error" role="alert"> Could not save the template: the name must not be blank and the amount must be 0.00 or more with at most two decimals.</span>
        )}
      </form>
    </>
  );
}
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';

export type Template = { name: string; amount: string; note: string };

export const templatesKey = (sheet: string) => ['sheet', sheet, 'templates'] as const;

/** The sheet's claim templates, by name. */
export function useTemplates(sheet: string): Template[] {
  const { data } = useQuery({
    queryKey: templatesKey(sheet),
    queryFn: () => getJson<Template[]>(`/api/sheets/${encodeURIComponent(sheet)}/templates`),
    enabled: sheet !== '',
  });
  return data ?? [];
}
// The app's fetch surface. A non-2xx REJECTS, so useQuery/useMutation surface the failure instead
// of a silent `if (res.ok)` that leaves the UI showing stale data.
/** A non-2xx answer; `status` lets a form tell a conflict (409) from a refusal. */
export class HttpError extends Error {
  constructor(message: string, readonly status: number) {
    super(message);
  }
}

/** The status a change is refused with while the screen is shown as of a date. */
export const AS_OF_REFUSED = 423;

/** Whether the screen is shown as of a date (the `asof` search param, see features/asof): every change is refused. */
function viewingAsOf(): boolean {
  return new URLSearchParams(window.location.search).get('asof') ? true : false;
}

async function send<T>(path: string, init?: RequestInit): Promise<T> {
  // An as-of view shows the sheet as it stood: a change asked for from it is refused, as any refused change, and
  // nothing reaches the store.
  if ((init?.method ?? 'GET') !== 'GET' && viewingAsOf()) {
    throw new HttpError(`${init?.method} ${path} -> refused: the screen is shown as of a date`, AS_OF_REFUSED);
  }
  const res = await fetch(path, init);
  if (!res.ok) {
    throw new HttpError(`${init?.method ?? 'GET'} ${path} -> ${res.status}`, res.status);
  }
  return res.status === 204 ? (undefined as T) : ((await res.json()) as T);
}

export function getJson<T>(path: string): Promise<T> {
  return send<T>(path);
}

export function postJson<T>(path: string, body: unknown): Promise<T> {
  return send<T>(path, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
  });
}

export function putJson<T>(path: string, body: unknown): Promise<T> {
  return send<T>(path, {
    method: 'PUT',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
  });
}
import { useRef } from 'react';

/** Guards a form's submit so a second submit made before the first has answered (a double click)
 *  is ignored: the store gets one record, not two. A ref, not mutation state, so it holds even
 *  for two clicks landing before the next render. */
export function useSubmitOnce(): (run: () => Promise<unknown>) => void {
  const busy = useRef(false);
  return (run) => {
    if (busy.current) return;
    busy.current = true;
    run()
      .catch(() => {
        // the mutation shows its own error
      })
      .finally(() => {
        busy.current = false;
      });
  };
}
import { createFileRoute } from '@tanstack/react-router';
import { asString, useSearchParam } from '../url/useSearchParam';
import { CurrentUser, SignIn } from '../features/session/SignIn';
import { SheetPicker } from '../features/session/SheetPicker';
import { SheetToday } from '../features/sheet/SheetToday';
